package com.bank.bidir.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "holdings")
public class Holding {
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)   // OWNING side — holds portfolio_id FK
    @JoinColumn(name = "portfolio_id")
    private Portfolio portfolio;

    private String symbol;
    private int quantity;
    private BigDecimal price;

    protected Holding() { }
    public Holding(String symbol, int quantity, BigDecimal price) {
        this.symbol = symbol; this.quantity = quantity; this.price = price;
    }
    // package-private: only the Portfolio aggregate sets this
    void setPortfolio(Portfolio p) { this.portfolio = p; }
    public BigDecimal marketValue() { return price.multiply(BigDecimal.valueOf(quantity)); }
}
```

