package com.bank.bidir.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

@Entity
@Table(name = "portfolios")
public class Portfolio {
    @Id private String id;
    private String ownerId;
    private String name;

    @OneToMany(mappedBy = "portfolio",       // INVERSE side — Hibernate ignores for FK
               cascade = CascadeType.ALL, orphanRemoval = true)
    private List<Holding> holdings = new ArrayList<>();

    protected Portfolio() { }
    public Portfolio(String id, String ownerId, String name) {
        this.id = id; this.ownerId = ownerId; this.name = name;
    }

    // HELPER: sets BOTH sides → in-memory graph and DB FK always agree
    public void addHolding(Holding h) {
        holdings.add(h);        // inverse side: in-memory list
        h.setPortfolio(this);   // owning side: FK that actually persists
    }
    public void removeHolding(Holding h) {
        holdings.remove(h);
        h.setPortfolio(null);   // owning side cleared → orphanRemoval DELETEs it
    }

    public BigDecimal totalValue() {
        return holdings.stream().map(Holding::marketValue)
                       .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
    public List<Holding> getHoldings() { return Collections.unmodifiableList(holdings); }
    public int holdingCount() { return holdings.size(); }
}
```

