package com.bank.bidir.service;

import com.bank.bidir.model.Holding;
import com.bank.bidir.model.Portfolio;
import com.bank.bidir.repository.PortfolioRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;

@Service
@RequiredArgsConstructor
@Slf4j
public class PortfolioService {

    private final PortfolioRepository portfolioRepo;

    @Transactional
    public void addHolding(String portfolioId, String symbol, int qty, BigDecimal price) {
        Portfolio pf = portfolioRepo.findById(portfolioId).orElseThrow();
        Holding h = new Holding(symbol, qty, price);
        pf.addHolding(h);   // sets BOTH sides → FK persisted AND in-memory list correct
        // count and total are now consistent in THIS transaction
        log.info("Added {}; count={} total={}", symbol, pf.holdingCount(), pf.totalValue());
    }
}
```
